per_case_results.actual_sql:
SELECT (SUM(CASE WHEN "preferred_foot" = 'left' THEN 1 ELSE 0 END) * 100.0 / COUNT(*)) AS percentage
FROM "Player"
WHERE YEAR("birthday") BETWEEN '1987' AND '1992';

SELECT "player_name", "player_api_id"
FROM "Player"
WHERE substr("birthday", 1, 7) = '1970-10';

SELECT 
    (COUNT(CASE WHEN "Player"."height" < 180 AND "Player"."overall_rating" > 70 THEN 1 END) * 100.0 / COUNT("Player"."id")) 
FROM "Player";
